<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $type
 * @property string $permission
 * @property string|null $target_type
 * @property string|null $target_id
 * @property string $summary
 * @property array $payload
 * @property string $status
 * @property string $requested_by
 * @property string|null $decided_by
 * @property string|null $decision_note
 * @property string|null $failure_reason
 * @property Carbon|null $decided_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class ApprovalRequest extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'apr';

    protected $fillable = [
        'type', 'permission', 'target_type', 'target_id', 'summary', 'payload', 'status', 'requested_by',
        'decided_by', 'decision_note', 'failure_reason', 'decided_at',
    ];

    protected function casts(): array
    {
        return [
            'payload' => 'array',
            'decided_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function requester(): BelongsTo
    {
        return $this->belongsTo(User::class, 'requested_by');
    }

    /** @return BelongsTo<User, $this> */
    public function decider(): BelongsTo
    {
        return $this->belongsTo(User::class, 'decided_by');
    }
}
